insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron', 'A neuron (American English), neurone (British English), or nerve cell, is a cell that is excitable, firing electric signals called action potentials. Neurons form neural networks in the nervous system, mainly in the central nervous system. Neurons receive and conduct impulses. They communicate with other cells via synapses, which are specialized connections that commonly use minute amounts of chemical neurotransmitters to pass the electric signal from the presynaptic neuron to the target cell through the synaptic gap. Neurons are the main components of nervous tissue in all animals except sponges and placozoans. Plants and fungi do not have nerve cells. Molecular evidence suggests that the ability to generate electric signals first appeared in life some 700 to 800 million years ago, during the Tonian period. Predecessors of neurons were the peptidergic secretory cells. They eventually gained new gene modules which enabled cells to create post-synaptic scaffolds and ion channels that generate fast electrical signals. The ability to generate electric signals was a key innovation in the evolution of the nervous system.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'A neuron (American English), neurone (British English), or nerve cell, is a cell that is excitable, firing electric signals called action potentials. Neurons form neural networks in the nervous system, mainly in the central nervous system. Neurons receive and conduct impulses. They communicate with other cells via synapses, which are specialized connections that commonly use minute amounts of chemical neurotransmitters to pass the electric signal from the presynaptic neuron to the target cell through the synaptic gap. Neurons are the main components of nervous tissue in all animals except sponges and placozoans. Plants and fungi do not have nerve cells. Molecular evidence suggests that the ability to generate electric signals first appeared in life some 700 to 800 million years ago, during the Tonian period. Predecessors of neurons were the peptidergic secretory cells. They eventually gained new gene modules which enabled cells to create post-synaptic scaffolds and ion channels that generate fast electrical signals. The ability to generate electric signals was a key innovation in the evolution of the nervous system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron', 'Neurons are typically classified into three types based on their function. Sensory neurons respond to stimuli such as touch, sound, or light that affect the cells of the sensory organs, and they send signals to the spinal cord and then to the sensorial area in the brain. Motor neurons receive signals from the brain and spinal cord to control everything from muscle contractions to glandular output. Interneurons connect neurons to other neurons within the same region of the brain or spinal cord. When multiple neurons are functionally connected together, they form what is called a neural circuit.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Neurons are typically classified into three types based on their function. Sensory neurons respond to stimuli such as touch, sound, or light that affect the cells of the sensory organs, and they send signals to the spinal cord and then to the sensorial area in the brain. Motor neurons receive signals from the brain and spinal cord to control everything from muscle contractions to glandular output. Interneurons connect neurons to other neurons within the same region of the brain or spinal cord. When multiple neurons are functionally connected together, they form what is called a neural circuit.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron', 'A neuron contains all the structures of other cells such as a nucleus, mitochondria, and Golgi bodies, but has additional unique structures such as an axon, and dendrites. The soma or cell body, is a compact structure, and the axon and dendrites are filaments extruding from the soma. Dendrites typically branch profusely and extend a few hundred micrometers from the soma. The axon leaves the soma at a swelling called the axon hillock and travels for as far as 1 meter in humans or more in other species. It branches but usually maintains a constant diameter. At the farthest tip of the axon''s branches are axon terminals, where the neuron can transmit a signal across the synapse to another cell. Neurons may lack dendrites or have no axons. The term neurite is used to describe either a dendrite or an axon, particularly when the cell is undifferentiated.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'A neuron contains all the structures of other cells such as a nucleus, mitochondria, and Golgi bodies, but has additional unique structures such as an axon, and dendrites. The soma or cell body, is a compact structure, and the axon and dendrites are filaments extruding from the soma. Dendrites typically branch profusely and extend a few hundred micrometers from the soma. The axon leaves the soma at a swelling called the axon hillock and travels for as far as 1 meter in humans or more in other species. It branches but usually maintains a constant diameter. At the farthest tip of the axon''s branches are axon terminals, where the neuron can transmit a signal across the synapse to another cell. Neurons may lack dendrites or have no axons. The term neurite is used to describe either a dendrite or an axon, particularly when the cell is undifferentiated.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron', 'Most neurons receive signals via the dendrites and soma and send out signals down the axon. At the majority of synapses, signals cross from the axon of one neuron to the dendrite of another. However, synapses can connect an axon to another axon or a dendrite to another dendrite. The signaling process is partly electrical and partly chemical. Neurons are electrically excitable, due to the maintenance of voltage gradients across their membranes. If the voltage changes by a large enough amount over a short interval, the neuron generates an all-or-nothing electrochemical pulse called an action potential. This potential travels rapidly along the axon and activates synaptic connections as it reaches them. Synaptic signals may be excitatory or inhibitory, increasing or reducing the net voltage that reaches the soma. In most cases, neurons are generated by neural stem cells during brain development and childhood. Neurogenesis largely ceases during adulthood in most areas of the brain.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Most neurons receive signals via the dendrites and soma and send out signals down the axon. At the majority of synapses, signals cross from the axon of one neuron to the dendrite of another. However, synapses can connect an axon to another axon or a dendrite to another dendrite. The signaling process is partly electrical and partly chemical. Neurons are electrically excitable, due to the maintenance of voltage gradients across their membranes. If the voltage changes by a large enough amount over a short interval, the neuron generates an all-or-nothing electrochemical pulse called an action potential. This potential travels rapidly along the axon and activates synaptic connections as it reaches them. Synaptic signals may be excitatory or inhibitory, increasing or reducing the net voltage that reaches the soma. In most cases, neurons are generated by neural stem cells during brain development and childhood. Neurogenesis largely ceases during adulthood in most areas of the brain.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron: Nervous system', 'Neurons are the primary components of the nervous system, along with the glial cells that give them structural and metabolic support. The nervous system is made up of the central nervous system, which includes the brain and spinal cord, and the peripheral nervous system, which includes the autonomic, enteric and somatic nervous systems. In vertebrates, the majority of neurons belong to the central nervous system, but some reside in peripheral ganglia, and many sensory neurons are situated in sensory organs such as the retina and cochlea. Axons may bundle into nerve fascicles that make up the nerves in the peripheral nervous system (like strands of wire that make up a cable). In the central nervous system bundles of axons are called nerve tracts.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Neurons are the primary components of the nervous system, along with the glial cells that give them structural and metabolic support. The nervous system is made up of the central nervous system, which includes the brain and spinal cord, and the peripheral nervous system, which includes the autonomic, enteric and somatic nervous systems. In vertebrates, the majority of neurons belong to the central nervous system, but some reside in peripheral ganglia, and many sensory neurons are situated in sensory organs such as the retina and cochlea. Axons may bundle into nerve fascicles that make up the nerves in the peripheral nervous system (like strands of wire that make up a cable). In the central nervous system bundles of axons are called nerve tracts.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron: Anatomy and histology', 'Neurons are highly specialized for the processing and transmission of cellular signals. Given the diversity of functions performed in different parts of the nervous system, there is a wide variety in their shape, size, and electrochemical properties. For instance, the soma of a neuron can vary from 4 to 100 micrometers in diameter. The soma is the body of the neuron. As it contains the nucleus, most protein synthesis occurs here. The nucleus can range from 3 to 18 micrometers in diameter. The dendrites of a neuron are cellular extensions with many branches. This overall shape and structure are referred to metaphorically as a dendritic tree. The branches form fractal patterns that repeat at multiple size scales. This fractal tree is where the majority of input to the neuron occurs via the dendritic spine.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Neurons are highly specialized for the processing and transmission of cellular signals. Given the diversity of functions performed in different parts of the nervous system, there is a wide variety in their shape, size, and electrochemical properties. For instance, the soma of a neuron can vary from 4 to 100 micrometers in diameter. The soma is the body of the neuron. As it contains the nucleus, most protein synthesis occurs here. The nucleus can range from 3 to 18 micrometers in diameter. The dendrites of a neuron are cellular extensions with many branches. This overall shape and structure are referred to metaphorically as a dendritic tree. The branches form fractal patterns that repeat at multiple size scales. This fractal tree is where the majority of input to the neuron occurs via the dendritic spine.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron: Anatomy and histology', 'The axon is a finer, cable-like projection that can extend tens, hundreds, or even tens of thousands of times the diameter of the soma in length. The axon primarily carries nerve signals away from the soma and carries some types of information back to it. Many neurons have only one axon, but this axon may—and usually will—undergo extensive branching, enabling communication with many target cells. The part of the axon where it emerges from the soma is called the axon hillock. Besides being an anatomical structure, the axon hillock also has the greatest density of voltage-dependent sodium channels. This makes it the most easily excited part of the neuron and the spike initiation zone for the axon. In electrophysiological terms, it has the most negative threshold potential. While the axon and axon hillock are generally involved in information outflow, this region can also receive input from other neurons. The axon terminal is found at the end of the axon farthest from the soma and contains synapses. Synaptic boutons are specialized structures where neurotransmitter chemicals are released to communicate with target neurons. In addition to synaptic boutons at the axon terminal, a neuron may have en passant boutons, which are located along the length of the axon.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The axon is a finer, cable-like projection that can extend tens, hundreds, or even tens of thousands of times the diameter of the soma in length. The axon primarily carries nerve signals away from the soma and carries some types of information back to it. Many neurons have only one axon, but this axon may—and usually will—undergo extensive branching, enabling communication with many target cells. The part of the axon where it emerges from the soma is called the axon hillock. Besides being an anatomical structure, the axon hillock also has the greatest density of voltage-dependent sodium channels. This makes it the most easily excited part of the neuron and the spike initiation zone for the axon. In electrophysiological terms, it has the most negative threshold potential. While the axon and axon hillock are generally involved in information outflow, this region can also receive input from other neurons. The axon terminal is found at the end of the axon farthest from the soma and contains synapses. Synaptic boutons are specialized structures where neurotransmitter chemicals are released to communicate with target neurons. In addition to synaptic boutons at the axon terminal, a neuron may have en passant boutons, which are located along the length of the axon.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Neuron: Anatomy and histology', 'The accepted view of the neuron attributes dedicated functions to its various anatomical components; however, dendrites and axons often act in ways contrary to their so-called main function. Axons and dendrites in the central nervous system are typically only about one micrometer thick, while some in the peripheral nervous system are much thicker. The soma is usually about 10–25 micrometers in diameter and often is not much larger than the cell nucleus it contains. The longest axon of a human motor neuron can be over a meter long, reaching from the base of the spine to the toes. Sensory neurons can have axons that run from the toes to the posterior column of the spinal cord, over 1.5 meters in adults. Giraffes have single axons several meters in length running along the entire length of their necks. Much of what is known about axonal function comes from studying the squid giant axon, an ideal experimental preparation because of its relatively immense size (0.5–1 millimeter thick, several centimeters long). Fully differentiated neurons are permanently postmitotic however, stem cells present in the adult brain may regenerate functional neurons throughout the life of an organism (see neurogenesis). Astrocytes are star-shaped glial cells that have been observed to turn into neurons by virtue of their stem cell-like characteristic of pluripotency.', 'Wikipedia: Neuron', 'https://en.wikipedia.org/w/index.php?title=Neuron&oldid=1378644558', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The accepted view of the neuron attributes dedicated functions to its various anatomical components; however, dendrites and axons often act in ways contrary to their so-called main function. Axons and dendrites in the central nervous system are typically only about one micrometer thick, while some in the peripheral nervous system are much thicker. The soma is usually about 10–25 micrometers in diameter and often is not much larger than the cell nucleus it contains. The longest axon of a human motor neuron can be over a meter long, reaching from the base of the spine to the toes. Sensory neurons can have axons that run from the toes to the posterior column of the spinal cord, over 1.5 meters in adults. Giraffes have single axons several meters in length running along the entire length of their necks. Much of what is known about axonal function comes from studying the squid giant axon, an ideal experimental preparation because of its relatively immense size (0.5–1 millimeter thick, several centimeters long). Fully differentiated neurons are permanently postmitotic however, stem cells present in the adult brain may regenerate functional neurons throughout the life of an organism (see neurogenesis). Astrocytes are star-shaped glial cells that have been observed to turn into neurons by virtue of their stem cell-like characteristic of pluripotency.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential', 'An action potential (also known as a nerve impulse or "spike" when in a neuron) is a series of quick changes in voltage across a cell membrane. An action potential occurs when the membrane potential of a specific cell rapidly rises and falls. This "depolarization" (physically, a reversal of the polarization of the membrane) then causes adjacent locations to similarly depolarize. Action potentials occur in several types of excitable cells, which include animal cells like neurons and muscle cells, as well as some plant cells. Certain endocrine cells such as pancreatic beta cells, and certain cells of the anterior pituitary gland are also excitable cells.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'An action potential (also known as a nerve impulse or "spike" when in a neuron) is a series of quick changes in voltage across a cell membrane. An action potential occurs when the membrane potential of a specific cell rapidly rises and falls. This "depolarization" (physically, a reversal of the polarization of the membrane) then causes adjacent locations to similarly depolarize. Action potentials occur in several types of excitable cells, which include animal cells like neurons and muscle cells, as well as some plant cells. Certain endocrine cells such as pancreatic beta cells, and certain cells of the anterior pituitary gland are also excitable cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential', 'In neurons, action potentials play a central role in cell–cell communication by providing for—or with regard to saltatory conduction, assisting—the propagation of signals along the neuron''s axon toward synaptic boutons situated at the ends of an axon; these signals can then connect with other neurons at synapses, or to motor cells or glands. In other types of cells, their main function is to activate intracellular processes. In muscle cells, for example, an action potential is the first step in the chain of events leading to contraction. In beta cells of the pancreas, they provoke release of insulin. The temporal sequence of action potentials generated by a neuron is called its "spike train". A neuron that emits an action potential, or nerve impulse, is often said to "fire".', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'In neurons, action potentials play a central role in cell–cell communication by providing for—or with regard to saltatory conduction, assisting—the propagation of signals along the neuron''s axon toward synaptic boutons situated at the ends of an axon; these signals can then connect with other neurons at synapses, or to motor cells or glands. In other types of cells, their main function is to activate intracellular processes. In muscle cells, for example, an action potential is the first step in the chain of events leading to contraction. In beta cells of the pancreas, they provoke release of insulin. The temporal sequence of action potentials generated by a neuron is called its "spike train". A neuron that emits an action potential, or nerve impulse, is often said to "fire".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential', 'Action potentials are generated by special types of voltage-gated ion channels embedded in a cell''s plasma membrane. These channels are shut when the membrane potential is near the (negative) resting potential of the cell, but they rapidly begin to open if the membrane potential increases to a precisely defined threshold voltage, "depolarising" the membrane. When the channels open, they allow an inward flow of sodium ions, which makes the interior of the cell more positive, which further raises the (negative) membrane potential. This then causes more channels to open, producing a greater electric current across the cell membrane and so on. The process proceeds explosively until all of the available ion channels are open, resulting in a large upswing in the membrane potential. The rapid influx of sodium ions causes the polarity of (i.e. the direction of the electric field across) the plasma membrane to reverse, and the ion channels then rapidly inactivate. As the sodium channels close, sodium ions can no longer enter the neuron, and they are then actively transported back out of the plasma membrane. Potassium channels are then activated, and there is an outward current of potassium ions, returning the electrochemical gradient to the resting state. Because few ions need to pass through to change the potential, the concentrations of ions on either side remain relatively unchanged during this process. After an action potential has occurred, there is a transient negative shift, called the afterhyperpolarization.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Action potentials are generated by special types of voltage-gated ion channels embedded in a cell''s plasma membrane. These channels are shut when the membrane potential is near the (negative) resting potential of the cell, but they rapidly begin to open if the membrane potential increases to a precisely defined threshold voltage, "depolarising" the membrane. When the channels open, they allow an inward flow of sodium ions, which makes the interior of the cell more positive, which further raises the (negative) membrane potential. This then causes more channels to open, producing a greater electric current across the cell membrane and so on. The process proceeds explosively until all of the available ion channels are open, resulting in a large upswing in the membrane potential. The rapid influx of sodium ions causes the polarity of (i.e. the direction of the electric field across) the plasma membrane to reverse, and the ion channels then rapidly inactivate. As the sodium channels close, sodium ions can no longer enter the neuron, and they are then actively transported back out of the plasma membrane. Potassium channels are then activated, and there is an outward current of potassium ions, returning the electrochemical gradient to the resting state. Because few ions need to pass through to change the potential, the concentrations of ions on either side remain relatively unchanged during this process. After an action potential has occurred, there is a transient negative shift, called the afterhyperpolarization.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential', 'In animal cells, there are two primary types of action potentials. One type is generated by voltage-gated sodium channels, the other by voltage-gated calcium channels. Sodium-based action potentials usually last for under one millisecond, but calcium-based action potentials may last for 100 milliseconds or longer. In some types of neurons, slow calcium spikes provide the driving force for a long burst of rapidly emitted sodium spikes. In cardiac muscle cells, on the other hand, an initial fast sodium spike provides a "primer" to provoke the rapid onset of a calcium spike, which then produces muscle contraction.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'In animal cells, there are two primary types of action potentials. One type is generated by voltage-gated sodium channels, the other by voltage-gated calcium channels. Sodium-based action potentials usually last for under one millisecond, but calcium-based action potentials may last for 100 milliseconds or longer. In some types of neurons, slow calcium spikes provide the driving force for a long burst of rapidly emitted sodium spikes. In cardiac muscle cells, on the other hand, an initial fast sodium spike provides a "primer" to provoke the rapid onset of a calcium spike, which then produces muscle contraction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential: Overview', 'Nearly all cell membranes in animals, plants and fungi maintain a voltage difference between the exterior and interior of the cell, called the membrane potential. A typical voltage across an animal cell membrane is −70 mV. This means that the interior of the cell has a negative voltage relative to the exterior. In most types of cells, the membrane potential usually stays fairly constant. Some types of cells, however, are electrically active in the sense that their voltages fluctuate over time. In some types of electrically active cells, including neurons and muscle cells, the voltage fluctuations frequently take the form of a rapid upward (positive) spike followed by a rapid fall. These up-and-down cycles are known as action potentials. Their duration varies considerably with the type of cell. In mammalian neurons, the entire up-and-down cycle takes only a few thousandths of a second, while in plant cells, an action potential may last as long as several seconds.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Nearly all cell membranes in animals, plants and fungi maintain a voltage difference between the exterior and interior of the cell, called the membrane potential. A typical voltage across an animal cell membrane is −70 mV. This means that the interior of the cell has a negative voltage relative to the exterior. In most types of cells, the membrane potential usually stays fairly constant. Some types of cells, however, are electrically active in the sense that their voltages fluctuate over time. In some types of electrically active cells, including neurons and muscle cells, the voltage fluctuations frequently take the form of a rapid upward (positive) spike followed by a rapid fall. These up-and-down cycles are known as action potentials. Their duration varies considerably with the type of cell. In mammalian neurons, the entire up-and-down cycle takes only a few thousandths of a second, while in plant cells, an action potential may last as long as several seconds.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential: Overview', 'The electrical properties of a cell are determined by the structure of its membrane. A cell membrane consists of a lipid bilayer of molecules in which larger protein molecules are embedded. The lipid bilayer is highly resistant to movement of electrically charged ions, so it functions as an insulator. The large membrane-embedded proteins, in contrast, provide channels through which ions can pass across the membrane. Action potentials are driven by channel proteins whose configuration switches between closed and open states as a function of the voltage difference between the interior and exterior of the cell. These voltage-sensitive proteins are known as voltage-gated ion channels.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The electrical properties of a cell are determined by the structure of its membrane. A cell membrane consists of a lipid bilayer of molecules in which larger protein molecules are embedded. The lipid bilayer is highly resistant to movement of electrically charged ions, so it functions as an insulator. The large membrane-embedded proteins, in contrast, provide channels through which ions can pass across the membrane. Action potentials are driven by channel proteins whose configuration switches between closed and open states as a function of the voltage difference between the interior and exterior of the cell. These voltage-sensitive proteins are known as voltage-gated ion channels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential: Process in a typical neuron', 'All cells in animal body tissues are electrically polarized – in other words, they maintain a voltage difference across the cell''s plasma membrane, known as the membrane potential. This electrical polarization results from a complex interplay between protein structures embedded in the membrane called ion pumps and ion channels. In neurons, the types of ion channels in the membrane usually vary across different parts of the cell, giving the dendrites, axon, and cell body different electrical properties. As a result, some parts of the membrane of a neuron may be excitable (capable of generating action potentials), whereas others are not. Recent studies have shown that the most excitable part of a neuron is the part after the axon hillock (the point where the axon leaves the cell body), which is called the axonal initial segment, but the axon and cell body are also excitable in most cases.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'All cells in animal body tissues are electrically polarized – in other words, they maintain a voltage difference across the cell''s plasma membrane, known as the membrane potential. This electrical polarization results from a complex interplay between protein structures embedded in the membrane called ion pumps and ion channels. In neurons, the types of ion channels in the membrane usually vary across different parts of the cell, giving the dendrites, axon, and cell body different electrical properties. As a result, some parts of the membrane of a neuron may be excitable (capable of generating action potentials), whereas others are not. Recent studies have shown that the most excitable part of a neuron is the part after the axon hillock (the point where the axon leaves the cell body), which is called the axonal initial segment, but the axon and cell body are also excitable in most cases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Action potential: Process in a typical neuron', 'Each excitable patch of membrane has two important levels of membrane potential: the resting potential, which is the value the membrane potential maintains as long as nothing perturbs the cell, and a higher value called the threshold potential. At the axon hillock of a typical neuron, the resting potential is around −70 millivolts (mV) and the threshold potential is around −55 mV. Synaptic inputs to a neuron cause the membrane to depolarize or hyperpolarize; that is, they cause the membrane potential to rise or fall. Action potentials are triggered when enough depolarization accumulates to bring the membrane potential up to threshold. When an action potential is triggered, the membrane potential abruptly shoots upward and then equally abruptly shoots back downward, often ending below the resting level, where it remains for some period of time. The shape of the action potential is stereotyped; this means that the rise and fall usually have approximately the same amplitude and time course for all action potentials in a given cell. (Exceptions are discussed later in the article) In most neurons, the entire process takes place in about a thousandth of a second. Many types of neurons emit action potentials constantly at rates of up to 10–100 per second. However, some types are much quieter, and may go for minutes or longer without emitting any action potentials.', 'Wikipedia: Action potential', 'https://en.wikipedia.org/w/index.php?title=Action_potential&oldid=1380609669', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Each excitable patch of membrane has two important levels of membrane potential: the resting potential, which is the value the membrane potential maintains as long as nothing perturbs the cell, and a higher value called the threshold potential. At the axon hillock of a typical neuron, the resting potential is around −70 millivolts (mV) and the threshold potential is around −55 mV. Synaptic inputs to a neuron cause the membrane to depolarize or hyperpolarize; that is, they cause the membrane potential to rise or fall. Action potentials are triggered when enough depolarization accumulates to bring the membrane potential up to threshold. When an action potential is triggered, the membrane potential abruptly shoots upward and then equally abruptly shoots back downward, often ending below the resting level, where it remains for some period of time. The shape of the action potential is stereotyped; this means that the rise and fall usually have approximately the same amplitude and time course for all action potentials in a given cell. (Exceptions are discussed later in the article) In most neurons, the entire process takes place in about a thousandth of a second. Many types of neurons emit action potentials constantly at rates of up to 10–100 per second. However, some types are much quieter, and may go for minutes or longer without emitting any action potentials.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse', 'Chemical synapses are biological junctions through which neurons'' signals can be sent to each other and to non-neuronal cells such as those in muscles or glands. Chemical synapses allow neurons to form circuits within the central nervous system. They are crucial to the biological computations that underlie perception and thought. They allow the nervous system to connect to and control other systems of the body. At a chemical synapse, one neuron releases neurotransmitter molecules into a small space (the synaptic cleft) that is adjacent to the postsynaptic cell (e.g., another neuron). The neurotransmitter molecules are contained within small sacs called synaptic vesicles, and are released into the synaptic cleft by exocytosis. These molecules then bind to neurotransmitter receptors on the postsynaptic cell. Finally, to terminate its action, the neurotransmitter is cleared from the cleft through one of several mechanisms, including enzymatic degradation or re-uptake, by specific transporters, either into the presynaptic cell or to neuroglia. The adult human brain is estimated to contain from 1014 to 5 × 1014 (100–500 trillion) synapses. Every cubic millimeter of cerebral cortex contains roughly a billion (short scale, i.e. 109) of them. The number of synapses in the human cerebral cortex has separately been estimated at 0.15 quadrillion (150 trillion).', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Chemical synapses are biological junctions through which neurons'' signals can be sent to each other and to non-neuronal cells such as those in muscles or glands. Chemical synapses allow neurons to form circuits within the central nervous system. They are crucial to the biological computations that underlie perception and thought. They allow the nervous system to connect to and control other systems of the body. At a chemical synapse, one neuron releases neurotransmitter molecules into a small space (the synaptic cleft) that is adjacent to the postsynaptic cell (e.g., another neuron). The neurotransmitter molecules are contained within small sacs called synaptic vesicles, and are released into the synaptic cleft by exocytosis. These molecules then bind to neurotransmitter receptors on the postsynaptic cell. Finally, to terminate its action, the neurotransmitter is cleared from the cleft through one of several mechanisms, including enzymatic degradation or re-uptake, by specific transporters, either into the presynaptic cell or to neuroglia. The adult human brain is estimated to contain from 1014 to 5 × 1014 (100–500 trillion) synapses. Every cubic millimeter of cerebral cortex contains roughly a billion (short scale, i.e. 109) of them. The number of synapses in the human cerebral cortex has separately been estimated at 0.15 quadrillion (150 trillion).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse', 'The word "synapse" was introduced by Sir Charles Scott Sherrington in 1897. Chemical synapses are not the only type of biological synapse: electrical and immunological synapses also exist. Without a qualifier, however, "synapse" commonly refers to chemical synapses.', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The word "synapse" was introduced by Sir Charles Scott Sherrington in 1897. Chemical synapses are not the only type of biological synapse: electrical and immunological synapses also exist. Without a qualifier, however, "synapse" commonly refers to chemical synapses.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse: Structure', 'Synapses are functional connections between neurons, or between neurons and other types of cells. A typical neuron gives rise to several thousand synapses, although there are some types that make far fewer. Most synapses connect axons to dendrites, but there are also other types of connections, including axon-to-cell-body, axon-to-axon, and dendrite-to-dendrite. Synapses are generally too small to be recognizable using a light microscope except as points where the membranes of two cells appear to touch, but their cellular elements can be visualized clearly using an electron microscope. Chemical synapses pass information directionally from a presynaptic cell to a postsynaptic cell and are therefore asymmetric in structure and function. The presynaptic axon terminal, or synaptic bouton, is a specialized area within the axon of the presynaptic cell that contains neurotransmitters enclosed in small membrane-bound spheres called synaptic vesicles (as well as a number of other supporting structures and organelles, such as mitochondria and endoplasmic reticulum). Some synaptic vesicles are docked at the presynaptic plasma membrane at regions called active zones. Immediately opposite is a region of the postsynaptic cell containing neurotransmitter receptors; for synapses between two neurons the postsynaptic region may be found on the dendrites or cell body. Immediately behind the postsynaptic membrane is an elaborate complex of interlinked proteins called the postsynaptic density (PSD).', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Synapses are functional connections between neurons, or between neurons and other types of cells. A typical neuron gives rise to several thousand synapses, although there are some types that make far fewer. Most synapses connect axons to dendrites, but there are also other types of connections, including axon-to-cell-body, axon-to-axon, and dendrite-to-dendrite. Synapses are generally too small to be recognizable using a light microscope except as points where the membranes of two cells appear to touch, but their cellular elements can be visualized clearly using an electron microscope. Chemical synapses pass information directionally from a presynaptic cell to a postsynaptic cell and are therefore asymmetric in structure and function. The presynaptic axon terminal, or synaptic bouton, is a specialized area within the axon of the presynaptic cell that contains neurotransmitters enclosed in small membrane-bound spheres called synaptic vesicles (as well as a number of other supporting structures and organelles, such as mitochondria and endoplasmic reticulum). Some synaptic vesicles are docked at the presynaptic plasma membrane at regions called active zones. Immediately opposite is a region of the postsynaptic cell containing neurotransmitter receptors; for synapses between two neurons the postsynaptic region may be found on the dendrites or cell body. Immediately behind the postsynaptic membrane is an elaborate complex of interlinked proteins called the postsynaptic density (PSD).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse: Structure', 'Proteins in the PSD are involved in anchoring and trafficking neurotransmitter receptors and modulating the activity of these receptors. The receptors and PSDs are often found in specialized protrusions from the main dendritic shaft called dendritic spines. Synapses may be described as symmetric or asymmetric. When examined under an electron microscope, asymmetric synapses are characterized by rounded vesicles in the presynaptic cell, and a prominent postsynaptic density. Asymmetric synapses are typically excitatory. Symmetric synapses in contrast have flattened or elongated vesicles, and do not contain a prominent postsynaptic density. Symmetric synapses are typically inhibitory. The synaptic cleft—also called synaptic gap—is a gap between the pre- and postsynaptic cells that is about 20 nm (0.02 μ) wide. The small volume of the cleft allows neurotransmitter concentration to be raised and lowered rapidly. An autapse is a chemical (or electrical) synapse formed when the axon of one neuron synapses with its own dendrites.', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Proteins in the PSD are involved in anchoring and trafficking neurotransmitter receptors and modulating the activity of these receptors. The receptors and PSDs are often found in specialized protrusions from the main dendritic shaft called dendritic spines. Synapses may be described as symmetric or asymmetric. When examined under an electron microscope, asymmetric synapses are characterized by rounded vesicles in the presynaptic cell, and a prominent postsynaptic density. Asymmetric synapses are typically excitatory. Symmetric synapses in contrast have flattened or elongated vesicles, and do not contain a prominent postsynaptic density. Symmetric synapses are typically inhibitory. The synaptic cleft—also called synaptic gap—is a gap between the pre- and postsynaptic cells that is about 20 nm (0.02 μ) wide. The small volume of the cleft allows neurotransmitter concentration to be raised and lowered rapidly. An autapse is a chemical (or electrical) synapse formed when the axon of one neuron synapses with its own dendrites.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse: Overview', 'Some authors consider signal transmission at a chemical synapse as a special case of paracrine signaling., while others treat it a separate signaling mechanism. Here is a summary of the sequence of events that take place in synaptic transmission from a presynaptic neuron to a postsynaptic cell. Each step is explained in more detail below. Note that with the exception of the final step, the entire process may run only a few hundred microseconds, in the fastest synapses. The process begins with a wave of electrochemical excitation called an action potential traveling along the membrane of the presynaptic cell, until it reaches the synapse. The electrical depolarization of the membrane at the synapse causes channels to open that are permeable to calcium ions. Calcium ions flow through the presynaptic membrane, rapidly increasing the calcium concentration in the interior. The high calcium concentration activates a set of calcium-sensitive proteins attached to vesicles that contain a neurotransmitter chemical. These proteins change shape, causing the membranes of some "docked" vesicles to fuse with the membrane of the presynaptic cell, thereby opening the vesicles and dumping their neurotransmitter contents into the synaptic cleft, the narrow space between the membranes of the pre- and postsynaptic cells.', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Some authors consider signal transmission at a chemical synapse as a special case of paracrine signaling., while others treat it a separate signaling mechanism. Here is a summary of the sequence of events that take place in synaptic transmission from a presynaptic neuron to a postsynaptic cell. Each step is explained in more detail below. Note that with the exception of the final step, the entire process may run only a few hundred microseconds, in the fastest synapses. The process begins with a wave of electrochemical excitation called an action potential traveling along the membrane of the presynaptic cell, until it reaches the synapse. The electrical depolarization of the membrane at the synapse causes channels to open that are permeable to calcium ions. Calcium ions flow through the presynaptic membrane, rapidly increasing the calcium concentration in the interior. The high calcium concentration activates a set of calcium-sensitive proteins attached to vesicles that contain a neurotransmitter chemical. These proteins change shape, causing the membranes of some "docked" vesicles to fuse with the membrane of the presynaptic cell, thereby opening the vesicles and dumping their neurotransmitter contents into the synaptic cleft, the narrow space between the membranes of the pre- and postsynaptic cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse: Overview', 'The neurotransmitter diffuses within the cleft. Some of it escapes, but some of it binds to chemical receptor molecules located on the membrane of the postsynaptic cell. The binding of neurotransmitter causes the receptor molecule to be activated in some way. Several types of activation are possible, as described in more detail below. In any case, this is the key step by which the synaptic process affects the behavior of the postsynaptic cell. Due to thermal vibration, the motion of atoms, vibrating about their equilibrium positions in a crystalline solid, neurotransmitter molecules eventually break loose from the receptors and drift away. The neurotransmitter is either reabsorbed by the presynaptic cell, and then repackaged for future release, or else it is broken down metabolically.', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The neurotransmitter diffuses within the cleft. Some of it escapes, but some of it binds to chemical receptor molecules located on the membrane of the postsynaptic cell. The binding of neurotransmitter causes the receptor molecule to be activated in some way. Several types of activation are possible, as described in more detail below. In any case, this is the key step by which the synaptic process affects the behavior of the postsynaptic cell. Due to thermal vibration, the motion of atoms, vibrating about their equilibrium positions in a crystalline solid, neurotransmitter molecules eventually break loose from the receptors and drift away. The neurotransmitter is either reabsorbed by the presynaptic cell, and then repackaged for future release, or else it is broken down metabolically.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse: Neurotransmitter release', 'The release of a neurotransmitter is triggered by the arrival of a nerve impulse (or action potential) and occurs through an unusually rapid process of cellular secretion (exocytosis). Within the presynaptic nerve terminal, vesicles containing neurotransmitter are localized near the synaptic membrane. The arriving action potential produces an influx of calcium ions through voltage-dependent, calcium-selective ion channels at the down stroke of the action potential (tail current). Calcium ions then bind to synaptotagmin proteins found within the membranes of the synaptic vesicles, allowing the vesicles to fuse with the presynaptic membrane. The fusion of a vesicle is a stochastic process, leading to frequent failure of synaptic transmission at the very small synapses that are typical for the central nervous system. Large chemical synapses (e.g. the neuromuscular junction), on the other hand, have a synaptic release probability, in effect, of 1. Vesicle fusion is driven by the action of a set of proteins in the presynaptic terminal known as SNAREs. As a whole, the protein complex or structure that mediates the docking and fusion of presynaptic vesicles is called the active zone. The membrane added by the fusion process is later retrieved by endocytosis and recycled for the formation of fresh neurotransmitter-filled vesicles.', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The release of a neurotransmitter is triggered by the arrival of a nerve impulse (or action potential) and occurs through an unusually rapid process of cellular secretion (exocytosis). Within the presynaptic nerve terminal, vesicles containing neurotransmitter are localized near the synaptic membrane. The arriving action potential produces an influx of calcium ions through voltage-dependent, calcium-selective ion channels at the down stroke of the action potential (tail current). Calcium ions then bind to synaptotagmin proteins found within the membranes of the synaptic vesicles, allowing the vesicles to fuse with the presynaptic membrane. The fusion of a vesicle is a stochastic process, leading to frequent failure of synaptic transmission at the very small synapses that are typical for the central nervous system. Large chemical synapses (e.g. the neuromuscular junction), on the other hand, have a synaptic release probability, in effect, of 1. Vesicle fusion is driven by the action of a set of proteins in the presynaptic terminal known as SNAREs. As a whole, the protein complex or structure that mediates the docking and fusion of presynaptic vesicles is called the active zone. The membrane added by the fusion process is later retrieved by endocytosis and recycled for the formation of fresh neurotransmitter-filled vesicles.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Chemical synapse: Neurotransmitter release', 'An exception to the general trend of neurotransmitter release by vesicular fusion is found in the type II receptor cells of mammalian taste buds. Here the neurotransmitter ATP is released directly from the cytoplasm into the synaptic cleft via voltage gated channels.', 'Wikipedia: Chemical synapse', 'https://en.wikipedia.org/w/index.php?title=Chemical_synapse&oldid=1378909138', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'An exception to the general trend of neurotransmitter release by vesicular fusion is found in the type II receptor cells of mammalian taste buds. Here the neurotransmitter ATP is released directly from the cytoplasm into the synaptic cleft via voltage gated channels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system', 'The autonomic nervous system (ANS), sometimes called the visceral nervous system and formerly the vegetative nervous system, is a division of the nervous system that operates internal organs, smooth muscle and glands. The autonomic nervous system is a control system that acts largely unconsciously and regulates bodily functions, such as the heart rate, its force of contraction, digestion, respiratory rate, pupillary response, urination, and sexual arousal. The autonomic nervous system has historically been branched into three divisions based on which organs and functions are being controlled by each system. This includes the enteric nervous system, which regulates the gastrointestinal tract, the parasympathetic nervous system and the sympathetic nervous system, which are responsible for, among other things, stimulation of the "rest and digest" and the fight-or-flight response (or "acute stress response"), respectively. In literature, the acronyms ENS, PSNS and SNS or SANS(where the A stands for autonomic) may be used to abbreviate the aforementioned terms.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The autonomic nervous system (ANS), sometimes called the visceral nervous system and formerly the vegetative nervous system, is a division of the nervous system that operates internal organs, smooth muscle and glands. The autonomic nervous system is a control system that acts largely unconsciously and regulates bodily functions, such as the heart rate, its force of contraction, digestion, respiratory rate, pupillary response, urination, and sexual arousal. The autonomic nervous system has historically been branched into three divisions based on which organs and functions are being controlled by each system. This includes the enteric nervous system, which regulates the gastrointestinal tract, the parasympathetic nervous system and the sympathetic nervous system, which are responsible for, among other things, stimulation of the "rest and digest" and the fight-or-flight response (or "acute stress response"), respectively. In literature, the acronyms ENS, PSNS and SNS or SANS(where the A stands for autonomic) may be used to abbreviate the aforementioned terms.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system', 'ANS is regulated by integrated reflexes through the brainstem to the spinal cord and organs. These functions include control of respiration, cardiac regulation, vasomotor activity, and certain reflex actions such as coughing, sneezing, swallowing and vomiting. Those are then subdivided into other areas and are also linked to autonomic subsystems and the peripheral nervous system. The hypothalamus, just above the brain stem, acts as an integrator for autonomic functions, receiving autonomic regulatory input from the limbic system. The vagus nerve plays a key role in the functioning of ANS, being the longest nerve of this system, and with both sensory and motor fibers, it helps with control over unconscious functions.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'ANS is regulated by integrated reflexes through the brainstem to the spinal cord and organs. These functions include control of respiration, cardiac regulation, vasomotor activity, and certain reflex actions such as coughing, sneezing, swallowing and vomiting. Those are then subdivided into other areas and are also linked to autonomic subsystems and the peripheral nervous system. The hypothalamus, just above the brain stem, acts as an integrator for autonomic functions, receiving autonomic regulatory input from the limbic system. The vagus nerve plays a key role in the functioning of ANS, being the longest nerve of this system, and with both sensory and motor fibers, it helps with control over unconscious functions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system', 'Although conflicting reports about its subdivisions exist in the literature, the autonomic nervous system has historically been considered a purely motor system, and has been divided into the aforementioned three branches of ENS, PSNS and SANS. The enteric nervous system however is a less recognized part of the autonomic nervous system. When it comes to the parasympathetic(calm, digesting, mating) amd the sympathetic(acute stress), in many cases, the two of these systems have complementary actions where one system activates a physiological response and the other inhibits it. An older simplification of the sympathetic and parasympathetic nervous systems as "excitatory" and "inhibitory" was overturned due to the many exceptions found. A more modern characterization is that the sympathetic nervous system is a "quick response mobilizing system" and the parasympathetic is a "more slowly activated dampening system", but even this has exceptions, such as in sexual arousal and orgasm, wherein both play a role. There are inhibitory and excitatory synapses between neurons. A third subsystem of neurons has been named as non-noradrenergic, non-cholinergic transmitters because they use other transmitters such as nitric oxide as a neurotransmitter. These functions are integral in autonomic function, in particular in the gut and the lungs.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Although conflicting reports about its subdivisions exist in the literature, the autonomic nervous system has historically been considered a purely motor system, and has been divided into the aforementioned three branches of ENS, PSNS and SANS. The enteric nervous system however is a less recognized part of the autonomic nervous system. When it comes to the parasympathetic(calm, digesting, mating) amd the sympathetic(acute stress), in many cases, the two of these systems have complementary actions where one system activates a physiological response and the other inhibits it. An older simplification of the sympathetic and parasympathetic nervous systems as "excitatory" and "inhibitory" was overturned due to the many exceptions found. A more modern characterization is that the sympathetic nervous system is a "quick response mobilizing system" and the parasympathetic is a "more slowly activated dampening system", but even this has exceptions, such as in sexual arousal and orgasm, wherein both play a role. There are inhibitory and excitatory synapses between neurons. A third subsystem of neurons has been named as non-noradrenergic, non-cholinergic transmitters because they use other transmitters such as nitric oxide as a neurotransmitter. These functions are integral in autonomic function, in particular in the gut and the lungs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system', 'Although the ANS is also known as the visceral nervous system and although most of its fibers carry non-somatic information to the CNS, many authors still consider it only connected with the motor side. Most autonomous functions are involuntary but they can often work in conjunction with the somatic nervous system which provides voluntary control. Overall, the ANS ensures the maintenance of vital functions and allows the body to effectively adapt to cycles of stress and recovery.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Although the ANS is also known as the visceral nervous system and although most of its fibers carry non-somatic information to the CNS, many authors still consider it only connected with the motor side. Most autonomous functions are involuntary but they can often work in conjunction with the somatic nervous system which provides voluntary control. Overall, the ANS ensures the maintenance of vital functions and allows the body to effectively adapt to cycles of stress and recovery.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system: Structure', 'The autonomic nervous system has been classically divided into the sympathetic, parasympathetic and enteric nervous systems. More modern classifications recognize other networks that are integral to different organs, such as the intrinsic cardiac nervous system. The sympathetic division emerges from the spinal cord in the thoracic and lumbar areas, terminating around L2-3. The parasympathetic division has craniosacral "outflow", meaning that the neurons begin at the cranial nerves (specifically the oculomotor nerve, facial nerve, glossopharyngeal nerve and vagus nerve) and sacral (S2-S4) spinal cord. These divisions are distinctive because they require a sequential two-neuron efferent pathway; the preganglionic neuron must first synapse onto a postganglionic neuron before innervating the target organ. The preganglionic, or first, neuron will have its nerve cell body in the central nervous system and will synapse at the postganglionic, or second, neuron''s cell body. The postganglionic neuron will then form junctions within the target organ.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The autonomic nervous system has been classically divided into the sympathetic, parasympathetic and enteric nervous systems. More modern classifications recognize other networks that are integral to different organs, such as the intrinsic cardiac nervous system. The sympathetic division emerges from the spinal cord in the thoracic and lumbar areas, terminating around L2-3. The parasympathetic division has craniosacral "outflow", meaning that the neurons begin at the cranial nerves (specifically the oculomotor nerve, facial nerve, glossopharyngeal nerve and vagus nerve) and sacral (S2-S4) spinal cord. These divisions are distinctive because they require a sequential two-neuron efferent pathway; the preganglionic neuron must first synapse onto a postganglionic neuron before innervating the target organ. The preganglionic, or first, neuron will have its nerve cell body in the central nervous system and will synapse at the postganglionic, or second, neuron''s cell body. The postganglionic neuron will then form junctions within the target organ.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system: Sympathetic division', 'The sympathetic nervous system consists of cells with bodies in the lateral grey column from T1 to L2/3. These cell bodies are "GVE" (general visceral efferent) neurons and are the preganglionic neurons. There are several locations upon which preganglionic neurons can synapse for their postganglionic neurons: paravertebral ganglia (3) of the sympathetic chain (these run on either side of the vertebral bodies) prevertebral ganglia (celiac ganglion, aorticorenal ganglion, superior mesenteric ganglion, inferior mesenteric ganglion) chromaffin cells of the adrenal medulla (this is the one exception to the two-neuron pathway rule: the synapse is directly efferent onto the target cell bodies) These ganglia provide the postganglionic neurons from which innervation of target organs follows. Examples of splanchnic (visceral) nerves are: cervical cardiac nerves and thoracic visceral nerves, which synapse in the sympathetic chain thoracic splanchnic nerves (greater, lesser, least), which synapse in the prevertebral ganglia These all contain afferent (sensory) nerves as well, known as GVA (general visceral afferent) neurons.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The sympathetic nervous system consists of cells with bodies in the lateral grey column from T1 to L2/3. These cell bodies are "GVE" (general visceral efferent) neurons and are the preganglionic neurons. There are several locations upon which preganglionic neurons can synapse for their postganglionic neurons: paravertebral ganglia (3) of the sympathetic chain (these run on either side of the vertebral bodies) prevertebral ganglia (celiac ganglion, aorticorenal ganglion, superior mesenteric ganglion, inferior mesenteric ganglion) chromaffin cells of the adrenal medulla (this is the one exception to the two-neuron pathway rule: the synapse is directly efferent onto the target cell bodies) These ganglia provide the postganglionic neurons from which innervation of target organs follows. Examples of splanchnic (visceral) nerves are: cervical cardiac nerves and thoracic visceral nerves, which synapse in the sympathetic chain thoracic splanchnic nerves (greater, lesser, least), which synapse in the prevertebral ganglia These all contain afferent (sensory) nerves as well, known as GVA (general visceral afferent) neurons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system: Parasympathetic division', 'The parasympathetic nervous system consists of cells with bodies in one of two locations: the brainstem (cranial nerves III, VII, IX, X) or the sacral spinal cord (S2, S3, S4). These are the preganglionic neurons, which synapse with postganglionic neurons in these locations: parasympathetic ganglia of the head: ciliary (cranial nerve III), geniculate (cranial nerve VII), pterygopalatine (cranial nerve VII and IX), and submandibular (cranial nerve VII and IX), tympanic nerve of VII with C9, C10, C5 (cranial nerves VII, XI, X, V) in promontory plexus in middle ear space trigeminal ganglion specially sensory (only mastication motor) is common with other ones in or near the wall of an organ innervated by the vagus (cranial nerve X) or sacral nerves plexus (S2, S3, S4) These ganglia provide the postganglionic neurons from which innervations of target organs follows. Examples are: the vagus nerve, which passes through the thorax and abdominal regions innervating, among other organs, the heart, lungs, liver and stomach', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The parasympathetic nervous system consists of cells with bodies in one of two locations: the brainstem (cranial nerves III, VII, IX, X) or the sacral spinal cord (S2, S3, S4). These are the preganglionic neurons, which synapse with postganglionic neurons in these locations: parasympathetic ganglia of the head: ciliary (cranial nerve III), geniculate (cranial nerve VII), pterygopalatine (cranial nerve VII and IX), and submandibular (cranial nerve VII and IX), tympanic nerve of VII with C9, C10, C5 (cranial nerves VII, XI, X, V) in promontory plexus in middle ear space trigeminal ganglion specially sensory (only mastication motor) is common with other ones in or near the wall of an organ innervated by the vagus (cranial nerve X) or sacral nerves plexus (S2, S3, S4) These ganglia provide the postganglionic neurons from which innervations of target organs follows. Examples are: the vagus nerve, which passes through the thorax and abdominal regions innervating, among other organs, the heart, lungs, liver and stomach');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Autonomic nervous system: Development of the enteric nervous system', 'Development of the enteric nervous system involves migration of cells from the vagal section of the neural crest, eventually populating the entire gastrointestinal tract. Throughout development, tyrosine kinase activity has roles in formation and regulation of enteric ganglia to influence spontaneous, rhythmic, slow waves in the gastrointestinal tract.', 'Wikipedia: Autonomic nervous system', 'https://en.wikipedia.org/w/index.php?title=Autonomic_nervous_system&oldid=1380093934', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Development of the enteric nervous system involves migration of cells from the vagal section of the neural crest, eventually populating the entire gastrointestinal tract. Throughout development, tyrosine kinase activity has roles in formation and regulation of enteric ganglia to influence spontaneous, rhythmic, slow waves in the gastrointestinal tract.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system', 'The endocrine system is a messenger system in an organism comprising feedback loops of hormones that are released by internal glands directly into the circulatory system and that target and regulate distant organs. In vertebrates, the hypothalamus is the neural control center for all endocrine systems. In humans, the major endocrine glands are the thyroid, parathyroid, pituitary, pineal, and adrenal glands, and the (male) testis and (female) ovaries. The hypothalamus, pancreas, and thymus also function as endocrine glands, among other functions. (The hypothalamus and pituitary glands are organs of the neuroendocrine system. One of the most important functions of the hypothalamus—it is located in the brain adjacent to the pituitary gland—is to link the endocrine system to the nervous system via the pituitary gland.) Other organs, such as the kidneys, also have roles within the endocrine system by secreting certain hormones. The study of the endocrine system and its disorders is known as endocrinology. The thyroid secretes thyroxine, the pituitary secretes growth hormone, the pineal secretes melatonin, the testis secretes testosterone, and the ovaries secrete estrogen and progesterone.', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The endocrine system is a messenger system in an organism comprising feedback loops of hormones that are released by internal glands directly into the circulatory system and that target and regulate distant organs. In vertebrates, the hypothalamus is the neural control center for all endocrine systems. In humans, the major endocrine glands are the thyroid, parathyroid, pituitary, pineal, and adrenal glands, and the (male) testis and (female) ovaries. The hypothalamus, pancreas, and thymus also function as endocrine glands, among other functions. (The hypothalamus and pituitary glands are organs of the neuroendocrine system. One of the most important functions of the hypothalamus—it is located in the brain adjacent to the pituitary gland—is to link the endocrine system to the nervous system via the pituitary gland.) Other organs, such as the kidneys, also have roles within the endocrine system by secreting certain hormones. The study of the endocrine system and its disorders is known as endocrinology. The thyroid secretes thyroxine, the pituitary secretes growth hormone, the pineal secretes melatonin, the testis secretes testosterone, and the ovaries secrete estrogen and progesterone.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system', 'Glands that signal each other in sequence are often referred to as an axis, such as the hypothalamic–pituitary–adrenal axis. In addition to the specialized endocrine organs mentioned above, many other organs that are part of other body systems have secondary endocrine functions, including bone, kidneys, liver, heart and gonads. For example, the kidney secretes the endocrine hormone erythropoietin. Hormones can be amino acid complexes, steroids, eicosanoids, leukotrienes, or prostaglandins. The endocrine system is contrasted both to exocrine glands, which secrete hormones to the outside of the body, and to the system known as paracrine signalling between cells over a relatively short distance. Endocrine glands have no ducts, are vascular, and commonly have intracellular vacuoles or granules that store their hormones. In contrast, exocrine glands, such as salivary glands, mammary glands, and submucosal glands within the gastrointestinal tract, tend to be much less vascular and have ducts or a hollow lumen.', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Glands that signal each other in sequence are often referred to as an axis, such as the hypothalamic–pituitary–adrenal axis. In addition to the specialized endocrine organs mentioned above, many other organs that are part of other body systems have secondary endocrine functions, including bone, kidneys, liver, heart and gonads. For example, the kidney secretes the endocrine hormone erythropoietin. Hormones can be amino acid complexes, steroids, eicosanoids, leukotrienes, or prostaglandins. The endocrine system is contrasted both to exocrine glands, which secrete hormones to the outside of the body, and to the system known as paracrine signalling between cells over a relatively short distance. Endocrine glands have no ducts, are vascular, and commonly have intracellular vacuoles or granules that store their hormones. In contrast, exocrine glands, such as salivary glands, mammary glands, and submucosal glands within the gastrointestinal tract, tend to be much less vascular and have ducts or a hollow lumen.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system: Major endocrine systems', 'The human endocrine system consists of several systems that operate via feedback loops. Several important feedback systems are mediated via the hypothalamus and pituitary.', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The human endocrine system consists of several systems that operate via feedback loops. Several important feedback systems are mediated via the hypothalamus and pituitary.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system: Glands', 'Endocrine glands are glands of the endocrine system that secrete their products, hormones, directly into interstitial spaces where they are absorbed into blood rather than through a duct. The major glands of the endocrine system include the pineal gland, pituitary gland, pancreas, ovaries, testes, thyroid gland, parathyroid gland, hypothalamus and adrenal glands. The hypothalamus and pituitary gland are neuroendocrine organs. The hypothalamus and the anterior pituitary are two out of the three endocrine glands that are important in cell signaling. They are both part of the HPA axis which is known to play a role in cell signaling in the nervous system. The hypothalamus is a key regulator of the autonomic nervous system. The endocrine system has three sets of endocrine outputs which include the magnocellular system, the parvocellular system, and autonomic intervention. The magnocellular is involved in the expression of oxytocin or vasopressin. The main role of the anterior pituitary gland is to produce and secrete tropic hormones. Some examples of tropic hormones secreted by the anterior pituitary gland include TSH, ACTH, GH, LH, and FSH. The parvocellular neurosecretory cell is involved in controlling the secretion of hormones from the anterior pituitary.', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Endocrine glands are glands of the endocrine system that secrete their products, hormones, directly into interstitial spaces where they are absorbed into blood rather than through a duct. The major glands of the endocrine system include the pineal gland, pituitary gland, pancreas, ovaries, testes, thyroid gland, parathyroid gland, hypothalamus and adrenal glands. The hypothalamus and pituitary gland are neuroendocrine organs. The hypothalamus and the anterior pituitary are two out of the three endocrine glands that are important in cell signaling. They are both part of the HPA axis which is known to play a role in cell signaling in the nervous system. The hypothalamus is a key regulator of the autonomic nervous system. The endocrine system has three sets of endocrine outputs which include the magnocellular system, the parvocellular system, and autonomic intervention. The magnocellular is involved in the expression of oxytocin or vasopressin. The main role of the anterior pituitary gland is to produce and secrete tropic hormones. Some examples of tropic hormones secreted by the anterior pituitary gland include TSH, ACTH, GH, LH, and FSH. The parvocellular neurosecretory cell is involved in controlling the secretion of hormones from the anterior pituitary.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system: Endocrine cells', 'There are many types of specialized endocrine cells that make up the larger tissues and glands of the endocrine system. The endocrine cells release hormones as molecular signals in endocrine signaling that target cells in more distant locations. In animals there are more than fifty such hormones released by the different endocrine glands. The pituitary gland, and the hypothalamus dominate most of the endocrine system. The pituitary gland is in two parts – the anterior pituitary, and the posterior pituitary. The posterior pituitary gland does not produce any hormone but stores and secretes hormones such as antidiuretic hormone (ADH) which is synthesized by supraoptic nucleus of hypothalamus and oxytocin which is synthesized by paraventricular nucleus of hypothalamus. ADH functions to help the body to retain water; this is important in maintaining a homeostatic balance between blood solutions and water. Oxytocin functions to induce uterine contractions, stimulate lactation, and allows for ejaculation. The follicular cells of the thyroid gland produce and secrete the thyroid hormones T3 and T4 in response to elevated levels of TRH, produced by the hypothalamus, and subsequent elevated levels of TSH, produced by the anterior pituitary, which further regulates the metabolic activity and rate of all cells, including cell growth and tissue differentiation.', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'There are many types of specialized endocrine cells that make up the larger tissues and glands of the endocrine system. The endocrine cells release hormones as molecular signals in endocrine signaling that target cells in more distant locations. In animals there are more than fifty such hormones released by the different endocrine glands. The pituitary gland, and the hypothalamus dominate most of the endocrine system. The pituitary gland is in two parts – the anterior pituitary, and the posterior pituitary. The posterior pituitary gland does not produce any hormone but stores and secretes hormones such as antidiuretic hormone (ADH) which is synthesized by supraoptic nucleus of hypothalamus and oxytocin which is synthesized by paraventricular nucleus of hypothalamus. ADH functions to help the body to retain water; this is important in maintaining a homeostatic balance between blood solutions and water. Oxytocin functions to induce uterine contractions, stimulate lactation, and allows for ejaculation. The follicular cells of the thyroid gland produce and secrete the thyroid hormones T3 and T4 in response to elevated levels of TRH, produced by the hypothalamus, and subsequent elevated levels of TSH, produced by the anterior pituitary, which further regulates the metabolic activity and rate of all cells, including cell growth and tissue differentiation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system: Endocrine cells', 'The parathyroid glands produce and secrete parathyroid hormone in response to low calcium. The epithelial cells of the parathyroid glands are richly supplied with blood from the Inferior thyroid artery and superior thyroid artery. Parathyroid hormone acts on bone, the kidneys, and the GI tract to increase calcium reabsorption and phosphate excretion. In addition, it also stimulates the conversion of vitamin D to its most active variant, 1,25-dihydroxyvitamin D3, which further stimulates calcium absorption in the GI tract. The pancreas contains nearly 1 to 2 million pancreatic islets the organ''s endocrine cells that secrete hormones, and acini. The acini secrete digestive enzymes. The pancreatic endocrine cells include', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The parathyroid glands produce and secrete parathyroid hormone in response to low calcium. The epithelial cells of the parathyroid glands are richly supplied with blood from the Inferior thyroid artery and superior thyroid artery. Parathyroid hormone acts on bone, the kidneys, and the GI tract to increase calcium reabsorption and phosphate excretion. In addition, it also stimulates the conversion of vitamin D to its most active variant, 1,25-dihydroxyvitamin D3, which further stimulates calcium absorption in the GI tract. The pancreas contains nearly 1 to 2 million pancreatic islets the organ''s endocrine cells that secrete hormones, and acini. The acini secrete digestive enzymes. The pancreatic endocrine cells include');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system: Endocrine cells', 'alpha cells that produce and secrete the glucagon to maintain homeostatic blood sugar. In response to low blood sugar levels, the release of glucagon stimulates glycogen stores in the liver to release sugar into the bloodstream to raise blood sugar to normal levels. Pancreatic beta cells make up 60% of the cells in the islets. Along with alpha cells, beta cells help to maintain glucose levels in the body. In response to high blood sugar, beta cells secrete insulin, a hypoglycemic hormone. Insulin decreases blood glucose level by helping cells to take up and metabolize glucose, and by stopping the liver from releasing more glucose. Insulin also performs other metabolic functions: causing muscle cells to take up amino acids, and inhibiting the breakdown and release of fats. Other glands include the thymus, the adrenal glands including the adrenal cortex, and the adrenal medulla, the ovary, the testicle and its Leydig cells', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'alpha cells that produce and secrete the glucagon to maintain homeostatic blood sugar. In response to low blood sugar levels, the release of glucagon stimulates glycogen stores in the liver to release sugar into the bloodstream to raise blood sugar to normal levels. Pancreatic beta cells make up 60% of the cells in the islets. Along with alpha cells, beta cells help to maintain glucose levels in the body. In response to high blood sugar, beta cells secrete insulin, a hypoglycemic hormone. Insulin decreases blood glucose level by helping cells to take up and metabolize glucose, and by stopping the liver from releasing more glucose. Insulin also performs other metabolic functions: causing muscle cells to take up amino acids, and inhibiting the breakdown and release of fats. Other glands include the thymus, the adrenal glands including the adrenal cortex, and the adrenal medulla, the ovary, the testicle and its Leydig cells');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Endocrine system: Development', 'The fetal endocrine system is one of the first systems to develop during prenatal development.', 'Wikipedia: Endocrine system', 'https://en.wikipedia.org/w/index.php?title=Endocrine_system&oldid=1380496431', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'The fetal endocrine system is one of the first systems to develop during prenatal development.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone', 'A hormone (from Ancient Greek ὁρμῶν (hormôn) ''setting in motion'') is a class of signaling molecules in multicellular organisms that are sent to distant organs or tissues by complex biological processes to regulate physiology and behavior. Hormones are required for the normal development of animals, plants and fungi. Due to the broad definition of a hormone (as a signaling molecule that exerts its effects far from its site of production), numerous kinds of molecules can be classified as hormones. Substances that can be considered hormones include eicosanoids (e.g. prostaglandins and thromboxanes), steroids (e.g. oestrogen and brassinosteroid), amino acid derivatives (e.g. epinephrine and auxin), protein or peptides (e.g. insulin and CLE peptides), and gases (e.g. ethylene and nitric oxide). Hormones are used to communicate between organs and tissues. In vertebrates, hormones are responsible for regulating a wide range of processes including both physiological processes and behavioral activities such as digestion, metabolism, respiration, sensory perception, sleep, excretion, lactation, stress induction, growth and development, movement, reproduction, and mood manipulation. In plants, hormones modulate almost all aspects of development, from germination to senescence.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'A hormone (from Ancient Greek ὁρμῶν (hormôn) ''setting in motion'') is a class of signaling molecules in multicellular organisms that are sent to distant organs or tissues by complex biological processes to regulate physiology and behavior. Hormones are required for the normal development of animals, plants and fungi. Due to the broad definition of a hormone (as a signaling molecule that exerts its effects far from its site of production), numerous kinds of molecules can be classified as hormones. Substances that can be considered hormones include eicosanoids (e.g. prostaglandins and thromboxanes), steroids (e.g. oestrogen and brassinosteroid), amino acid derivatives (e.g. epinephrine and auxin), protein or peptides (e.g. insulin and CLE peptides), and gases (e.g. ethylene and nitric oxide). Hormones are used to communicate between organs and tissues. In vertebrates, hormones are responsible for regulating a wide range of processes including both physiological processes and behavioral activities such as digestion, metabolism, respiration, sensory perception, sleep, excretion, lactation, stress induction, growth and development, movement, reproduction, and mood manipulation. In plants, hormones modulate almost all aspects of development, from germination to senescence.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone', 'Hormones affect distant cells by binding to specific receptor proteins in the target cell, resulting in a change in cell function. When a hormone binds to the receptor, it results in the activation of a signal transduction pathway that typically activates gene transcription, resulting in increased expression of target proteins. Hormones can also act in non-genomic pathways that synergize with genomic effects. Water-soluble hormones (such as peptides and amines) generally act on the surface of target cells via second messengers. Lipid soluble hormones, (such as steroids) generally pass through the plasma membrane of target cells (both cytoplasmic and nuclear) to act within their nuclei. Brassinosteroids, a type of polyhydroxysteroids, are a sixth class of plant hormones and may be useful as an anticancer drug for endocrine-responsive tumors to cause apoptosis and limit plant growth. Despite being lipid soluble, they nevertheless attach to their receptor at the cell surface. In vertebrates, endocrine glands are specialized organs that secrete hormones into the endocrine signaling system. Hormone secretion occurs in response to specific biochemical signals and is often subject to negative feedback regulation. For instance, high blood sugar (serum glucose concentration) promotes insulin synthesis. Insulin then acts to reduce glucose levels and maintain homeostasis, leading to reduced insulin levels.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Hormones affect distant cells by binding to specific receptor proteins in the target cell, resulting in a change in cell function. When a hormone binds to the receptor, it results in the activation of a signal transduction pathway that typically activates gene transcription, resulting in increased expression of target proteins. Hormones can also act in non-genomic pathways that synergize with genomic effects. Water-soluble hormones (such as peptides and amines) generally act on the surface of target cells via second messengers. Lipid soluble hormones, (such as steroids) generally pass through the plasma membrane of target cells (both cytoplasmic and nuclear) to act within their nuclei. Brassinosteroids, a type of polyhydroxysteroids, are a sixth class of plant hormones and may be useful as an anticancer drug for endocrine-responsive tumors to cause apoptosis and limit plant growth. Despite being lipid soluble, they nevertheless attach to their receptor at the cell surface. In vertebrates, endocrine glands are specialized organs that secrete hormones into the endocrine signaling system. Hormone secretion occurs in response to specific biochemical signals and is often subject to negative feedback regulation. For instance, high blood sugar (serum glucose concentration) promotes insulin synthesis. Insulin then acts to reduce glucose levels and maintain homeostasis, leading to reduced insulin levels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone', 'Upon secretion, water-soluble hormones are readily transported through the circulatory system. Lipid-soluble hormones must bind to carrier plasma glycoproteins (e.g., thyroxine-binding globulin (TBG)) to form ligand-protein complexes. Some hormones, such as insulin and growth hormones, can be released into the bloodstream already fully active. Other hormones, called prohormones, must be activated in certain cells through a series of steps that are usually tightly controlled. The endocrine system secretes hormones directly into the bloodstream, typically via fenestrated capillaries, whereas the exocrine system secretes its hormones indirectly using ducts. Hormones with paracrine function diffuse through the interstitial spaces to nearby target tissue. Plants lack specialized organs for the secretion of hormones, although there is a spatial distribution of hormone production. For example, the hormone auxin is produced mainly at the tips of young leaves and in the shoot apical meristem. The lack of specialised glands means that the main site of hormone production can change throughout the life of a plant, and the site of production is dependent on the plant''s age and environment.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Upon secretion, water-soluble hormones are readily transported through the circulatory system. Lipid-soluble hormones must bind to carrier plasma glycoproteins (e.g., thyroxine-binding globulin (TBG)) to form ligand-protein complexes. Some hormones, such as insulin and growth hormones, can be released into the bloodstream already fully active. Other hormones, called prohormones, must be activated in certain cells through a series of steps that are usually tightly controlled. The endocrine system secretes hormones directly into the bloodstream, typically via fenestrated capillaries, whereas the exocrine system secretes its hormones indirectly using ducts. Hormones with paracrine function diffuse through the interstitial spaces to nearby target tissue. Plants lack specialized organs for the secretion of hormones, although there is a spatial distribution of hormone production. For example, the hormone auxin is produced mainly at the tips of young leaves and in the shoot apical meristem. The lack of specialised glands means that the main site of hormone production can change throughout the life of a plant, and the site of production is dependent on the plant''s age and environment.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone: Introduction and overview', 'Hormone producing cells are found in the endocrine glands, such as the thyroid gland, ovaries, and testes. Hormonal signaling involves the following steps: Recognition of the hormone by an associated cell membrane or intracellular receptor protein. Relay and amplification of the received hormonal signal via a signal transduction process: This then leads to a cellular response. The reaction of the target cells may then be recognized by the original hormone-producing cells, leading to a downregulation in hormone production. This is an example of a homeostatic negative feedback loop. Exocytosis and other methods of membrane transport are used to secrete hormones when the endocrine glands are signaled. The hierarchical model is an oversimplification of the hormonal signaling process. Cellular recipients of a particular hormonal signal may be one of several cell types that reside within a number of different tissues, as is the case for insulin, which triggers a diverse range of systemic physiological effects. Different tissue types may also respond differently to the same hormonal signal.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Hormone producing cells are found in the endocrine glands, such as the thyroid gland, ovaries, and testes. Hormonal signaling involves the following steps: Recognition of the hormone by an associated cell membrane or intracellular receptor protein. Relay and amplification of the received hormonal signal via a signal transduction process: This then leads to a cellular response. The reaction of the target cells may then be recognized by the original hormone-producing cells, leading to a downregulation in hormone production. This is an example of a homeostatic negative feedback loop. Exocytosis and other methods of membrane transport are used to secrete hormones when the endocrine glands are signaled. The hierarchical model is an oversimplification of the hormonal signaling process. Cellular recipients of a particular hormonal signal may be one of several cell types that reside within a number of different tissues, as is the case for insulin, which triggers a diverse range of systemic physiological effects. Different tissue types may also respond differently to the same hormonal signal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone: Arnold Adolph Berthold (1849)', 'Arnold Adolph Berthold was a German physiologist and zoologist, who, in 1849, had a question about the function of the testes. He noticed in castrated roosters that they did not have the same sexual behaviors as roosters with their testes intact. He decided to run an experiment on male roosters to examine this phenomenon. He kept a group of roosters with their testes intact, and saw that they had normally sized wattles and combs (secondary sexual organs), a normal crow, and normal sexual and aggressive behaviors. He also had a group with their testes surgically removed, and noticed that their secondary sexual organs were decreased in size, had a weak crow, did not have sexual attraction towards females, and were not aggressive. He realized that this organ was essential for these behaviors, but he did not know how. To test this further, he removed one testis and placed it in the abdominal cavity. The roosters acted and had normal physical anatomy. He was able to see that the location of the testes does not matter. He then wanted to see if it was a genetic factor that was involved in the testes that provided these functions. He transplanted a testis from another rooster to a rooster with one testis removed, and saw that they had normal behavior and physical anatomy as well. Berthold determined that the location or genetic factors of the testes do not matter in relation to sexual organs and behaviors, but that some chemical in the testes is being secreted is causing this phenomenon. It was later identified that this factor was the hormone testosterone.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Arnold Adolph Berthold was a German physiologist and zoologist, who, in 1849, had a question about the function of the testes. He noticed in castrated roosters that they did not have the same sexual behaviors as roosters with their testes intact. He decided to run an experiment on male roosters to examine this phenomenon. He kept a group of roosters with their testes intact, and saw that they had normally sized wattles and combs (secondary sexual organs), a normal crow, and normal sexual and aggressive behaviors. He also had a group with their testes surgically removed, and noticed that their secondary sexual organs were decreased in size, had a weak crow, did not have sexual attraction towards females, and were not aggressive. He realized that this organ was essential for these behaviors, but he did not know how. To test this further, he removed one testis and placed it in the abdominal cavity. The roosters acted and had normal physical anatomy. He was able to see that the location of the testes does not matter. He then wanted to see if it was a genetic factor that was involved in the testes that provided these functions. He transplanted a testis from another rooster to a rooster with one testis removed, and saw that they had normal behavior and physical anatomy as well. Berthold determined that the location or genetic factors of the testes do not matter in relation to sexual organs and behaviors, but that some chemical in the testes is being secreted is causing this phenomenon. It was later identified that this factor was the hormone testosterone.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone: Charles and Francis Darwin (1880)', 'Although known primarily for his work on the Theory of Evolution, Charles Darwin was also keenly interested in plants. Through the 1870s, he and his son Francis studied the movement of plants towards light. They were able to show that light is perceived at the tip of a young stem (the coleoptile), whereas the bending occurs lower down the stem. They proposed that a ''transmissible substance'' communicated the direction of light from the tip down to the stem. The idea of a ''transmissible substance'' was initially dismissed by other plant biologists, but their work later led to the discovery of the first plant hormone. In the 1920s Dutch scientist Frits Warmolt Went and Russian scientist Nikolai Cholodny (working independently of each other) conclusively showed that asymmetric accumulation of a growth hormone was responsible for this bending. In 1933 this hormone was finally isolated by Kögl, Haagen-Smit and Erxleben and given the name ''auxin''.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'Although known primarily for his work on the Theory of Evolution, Charles Darwin was also keenly interested in plants. Through the 1870s, he and his son Francis studied the movement of plants towards light. They were able to show that light is perceived at the tip of a young stem (the coleoptile), whereas the bending occurs lower down the stem. They proposed that a ''transmissible substance'' communicated the direction of light from the tip down to the stem. The idea of a ''transmissible substance'' was initially dismissed by other plant biologists, but their work later led to the discovery of the first plant hormone. In the 1920s Dutch scientist Frits Warmolt Went and Russian scientist Nikolai Cholodny (working independently of each other) conclusively showed that asymmetric accumulation of a growth hormone was responsible for this bending. In 1933 this hormone was finally isolated by Kögl, Haagen-Smit and Erxleben and given the name ''auxin''.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone: Oliver and Schäfer (1894)', 'British physician George Oliver and physiologist Edward Albert Schäfer, professor at University College London, collaborated on the physiological effects of adrenal extracts. They first published their findings in two reports in 1894, a full publication followed in 1895. Though frequently falsely attributed to secretin, found in 1902 by Bayliss and Starling, Oliver and Schäfer''s adrenal extract containing adrenaline, the substance causing the physiological changes, was the first hormone to be discovered. The term hormone would later be coined by Starling.', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'British physician George Oliver and physiologist Edward Albert Schäfer, professor at University College London, collaborated on the physiological effects of adrenal extracts. They first published their findings in two reports in 1894, a full publication followed in 1895. Though frequently falsely attributed to secretin, found in 1902 by Bayliss and Starling, Oliver and Schäfer''s adrenal extract containing adrenaline, the substance causing the physiological changes, was the first hormone to be discovered. The term hormone would later be coined by Starling.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'nervous-endocrine', 'Hormone: Bayliss and Starling (1902)', 'William Bayliss and Ernest Starling, a physiologist and biologist respectively, wanted to see if the nervous system had an impact on the digestive system. From the work of Martin Heidenhain and Claude Bernard, they knew that the pancreas was involved in the secretion of digestive fluids after the passage of food from the stomach to the intestines, which they believed to be due to the nervous system. They cut the nerves to the pancreas in an animal model and discovered that it was not nerve impulses that controlled secretion from the pancreas. It was determined that a factor secreted from the intestines into the bloodstream was stimulating the pancreas to secrete digestive fluids. This was named secretin: a hormone. In 1905, Starling coined the word hormone from the Greek to arouse or excite which he defined as "the chemical messengers which speeding from cell to cell along the blood stream, may coordinate the activities and growth of different parts of the body".', 'Wikipedia: Hormone', 'https://en.wikipedia.org/w/index.php?title=Hormone&oldid=1373836983', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'nervous-endocrine' and body = 'William Bayliss and Ernest Starling, a physiologist and biologist respectively, wanted to see if the nervous system had an impact on the digestive system. From the work of Martin Heidenhain and Claude Bernard, they knew that the pancreas was involved in the secretion of digestive fluids after the passage of food from the stomach to the intestines, which they believed to be due to the nervous system. They cut the nerves to the pancreas in an animal model and discovered that it was not nerve impulses that controlled secretion from the pancreas. It was determined that a factor secreted from the intestines into the bloodstream was stimulating the pancreas to secrete digestive fluids. This was named secretin: a hormone. In 1905, Starling coined the word hormone from the Greek to arouse or excite which he defined as "the chemical messengers which speeding from cell to cell along the blood stream, may coordinate the activities and growth of different parts of the body".');
